// limiter.go
package ratelimit

import (
	"errors"
	"time"
)

// Clock is an interface for time abstraction to allow testing.
type Clock interface {
	Now() time.Time
	Since(time.Time) time.Duration
}

// RealClock implements Clock using time.Now.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }
func (RealClock) Since(t time.Time) time.Duration { return time.Since(t) }

// TokenBucket is a concurrency-safe token bucket rate limiter.
type TokenBucket struct {
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
	mu       sync.Mutex
}

// New creates a new TokenBucket.
// capacity: maximum number of tokens in the bucket.
// rate: tokens added per second.
// clock: injectable clock for testing.
func New(capacity, rate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("rate must be positive")
	}
	if clock == nil {
		return nil, errors.New("clock must not be nil")
	}
	return &TokenBucket{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN checks if n tokens are available. If so, it consumes them and returns true.
// If not, it returns false without consuming tokens.
func (tb *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last)
	tb.last = now

	// Add tokens based on elapsed time
	tb.tokens += tb.rate * elapsed.Seconds()
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}
